package com.turboio.androidtests;

import android.app.*;import android.content.*;import android.os.*;import android.util.Base64;
import java.io.*;import java.lang.reflect.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import org.json.*;

/** Upgrade audit exports only hashes/counts. Keystore tests use isolated prefs,
 * synthetic credentials and two instrumentation processes; no HTTP or capture. */
public final class MaterialUpgradeProbe extends Instrumentation {
 private ClassLoader loader;private String nonce,phase;private int checks;
 private Class<?> type(String n)throws Exception{return loader.loadClass("com.turboio.addon."+n);}
 private Object call(Object o,String n,Class<?>[] t,Object...a)throws Exception{Class<?> c=o instanceof Class?(Class<?>)o:o.getClass();Method m=c.getDeclaredMethod(n,t);m.setAccessible(true);return m.invoke(o instanceof Class?null:o,a);}
 private Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private void check(boolean value,String code){checks++;if(!value)throw new IllegalStateException(code);}
 private String sha(byte[] bytes)throws Exception{StringBuilder out=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
 private Object settings(Context context)throws Exception{Constructor<?> c=type("MaterialSettings").getDeclaredConstructor(Context.class);c.setAccessible(true);return c.newInstance(context);}
 private byte[] encode(Object config)throws Exception{return (byte[])call(config,"encode",new Class<?>[0]);}
 private byte[] unseal(String value,String aad)throws Exception{KeyStore keys=KeyStore.getInstance("AndroidKeyStore");keys.load(null);SecretKey key=(SecretKey)keys.getKey("io.agent.materials.config.v1",null);byte[] raw=Base64.decode(value,Base64.NO_WRAP);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,Arrays.copyOf(raw,12)));c.updateAAD(aad.getBytes(StandardCharsets.UTF_8));return c.doFinal(Arrays.copyOfRange(raw,12,raw.length));}
 private String seal(byte[] bytes)throws Exception{KeyStore keys=KeyStore.getInstance("AndroidKeyStore");keys.load(null);SecretKey key=(SecretKey)keys.getKey("io.agent.materials.config.v1",null);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key);c.updateAAD("io-agent/material-connection/1".getBytes(StandardCharsets.UTF_8));byte[] encrypted=c.doFinal(bytes),raw=new byte[12+encrypted.length];System.arraycopy(c.getIV(),0,raw,0,12);System.arraycopy(encrypted,0,raw,12,encrypted.length);return Base64.encodeToString(raw,Base64.NO_WRAP);}
 private JSONObject file(File f)throws Exception{if(!f.exists())return new JSONObject().put("exists",false);check(f.isFile()&&!Files.isSymbolicLink(f.toPath())&&f.length()<=33554432,"AUDIT_FILE_INVALID");return new JSONObject().put("exists",true).put("bytes",f.length()).put("sha256",sha(Files.readAllBytes(f.toPath())));}
 private JSONObject audit(Context target)throws Exception{
  Object config=call(settings(target),"load",new Class<?>[0]);check(config!=null,"MATERIAL_CONFIG_MISSING");Object connection=field(config,"connection");String account=(String)field(config,"account"),binding=(String)call(connection,"binding",new Class<?>[0]);
  JSONObject out=new JSONObject().put("config_sha256",sha(encode(config))).put("enabled",field(config,"enabled")).put("credential_expired",((Long)field(connection,"expiresAt"))<=System.currentTimeMillis());
  File files=target.getFilesDir(),old=new File(files,"material-accounts/"+account),current=new File(files,"material-accounts-v2/"+account);String[] names={"material-outbox/"+binding+"/state.json","lifelog-import/"+binding+"/"+account+"/state.json","lifelog-revisions/"+binding+"/"+account+"/state.json"};JSONArray legacy=new JSONArray(),next=new JSONArray();
  for(String name:names){legacy.put(file(new File(old,name)));next.put(file(new File(current,name)));}
  out.put("legacy",legacy).put("current",next).put("local_library",file(new File(old,"local-library/state.json"))).put("migration",file(new File(current,"migration/"+binding+"/state.json")));
  SharedPreferences p=target.getSharedPreferences("io_agent_materials_v1",0);out.put("new_settings_present",p.contains("material_sealed_v2")).put("original_encrypted_backup_present",p.contains("material_backup_v1"));
  if(p.contains("material_sealed_v2")){Object projection=call(type("MaterialConfig"),"decode",new Class<?>[]{byte[].class},unseal(p.getString("sealed",null),"io-agent/material-connection/1"));out.put("rollback_paused",!((Boolean)field(projection,"enabled")));}
  return out;
 }
 @Override public void onCreate(Bundle args){super.onCreate(args);nonce=args.getString("probe_id","");phase=args.getString("phase","");start();}
 @Override public void onStart(){Bundle result=new Bundle();result.putString("probe_id",nonce);Context target=getTargetContext();String name="io_material_upgrade_probe_"+nonce;boolean retain=false;try{
  check(nonce.matches("[a-f0-9]{32}"),"PROBE_ID_INVALID");loader=target.getClassLoader();
  if(phase.equals("audit")){result.putString("audit",audit(target).toString());}
  else{
   SharedPreferences real=target.getSharedPreferences("io_agent_materials_v1",0),p=target.getSharedPreferences(name,0);Map<String,?> before=new HashMap<>(real.getAll());Context wrapped=new ContextWrapper(target){@Override public SharedPreferences getSharedPreferences(String ignored,int mode){return p;}};Object store=settings(wrapped);
   if(phase.equals("seed")){
    check(p.getAll().isEmpty(),"PROBE_NAMESPACE_OCCUPIED");JSONObject wire=new JSONObject().put("format","turboio-material-sync/1").put("base_url","https://synthetic.invalid/v1").put("owner_id","synthetic-upgrade").put("producer_id","synthetic-phone").put("server_id","synthetic-server").put("token",String.join("",Collections.nCopies(43,"A"))).put("token_id","00000000-0000-4000-8000-000000000001").put("expires_at",java.time.Instant.ofEpochMilli(System.currentTimeMillis()+3600000).toString());Object connection=call(type("MaterialConnection"),"parse",new Class<?>[]{byte[].class,long.class},wire.toString().getBytes(StandardCharsets.UTF_8),System.currentTimeMillis());Constructor<?> ctor=type("MaterialConfig").getDeclaredConstructor(type("MaterialConnection"),String.class,boolean.class);ctor.setAccessible(true);Object config=ctor.newInstance(connection,String.join("",Collections.nCopies(64,"a")),true);
    call(store,"save",new Class<?>[]{type("MaterialConfig")},config);String old=seal(encode(config));check(p.edit().clear().putString("sealed",old).commit(),"SEED_FAILED");Object migrated=call(store,"load",new Class<?>[0]);check(Arrays.equals(encode(config),encode(migrated)),"MIGRATION_CHANGED_CONFIG");check(old.equals(p.getString("material_backup_v1",null)),"BACKUP_CHANGED");Object projection=call(type("MaterialConfig"),"decode",new Class<?>[]{byte[].class},unseal(p.getString("sealed",null),"io-agent/material-connection/1"));check(!((Boolean)field(projection,"enabled")),"ROLLBACK_NOT_PAUSED");check(p.contains("material_sealed_v2"),"NEW_SLOT_MISSING");retain=true;
   }else if(phase.equals("reopen")){
    check(p.contains("material_sealed_v2")&&p.contains("material_backup_v1"),"SEED_NOT_PERSISTED");Object loaded=call(store,"load",new Class<?>[0]);check((Boolean)field(loaded,"enabled"),"RESTART_LOST_ENABLED");byte[] old=unseal(p.getString("material_backup_v1",null),"io-agent/material-connection/1");check(Arrays.equals(old,encode(loaded)),"RESTART_CHANGED_CONFIG");String valid=p.getString("material_sealed_v2",null);byte[] damaged=Base64.decode(valid,Base64.NO_WRAP);damaged[damaged.length-1]^=1;check(p.edit().putString("material_sealed_v2",Base64.encodeToString(damaged,Base64.NO_WRAP)).commit(),"TAMPER_SEED_FAILED");boolean rejected=false;try{call(store,"load",new Class<?>[0]);}catch(InvocationTargetException expected){rejected=true;}check(rejected,"TAMPER_FELL_BACK");check(p.edit().putString("material_sealed_v2",valid).putString("sealed",seal(old)).commit(),"LEGACY_CHANGE_SEED_FAILED");rejected=false;try{call(store,"load",new Class<?>[0]);}catch(InvocationTargetException expected){rejected=true;}check(rejected,"LEGACY_CHANGE_IGNORED");
   }else if(!phase.equals("cleanup"))throw new IllegalStateException("PROBE_PHASE_INVALID");
   check(before.equals(real.getAll()),"REAL_SETTINGS_CHANGED");result.putBoolean("real_settings_unchanged",true);if(!retain)check(target.deleteSharedPreferences(name),"TEST_PREFS_NOT_REMOVED");result.putBoolean("test_namespace_retained_for_restart",retain);
  }
  result.putInt("checks",checks);result.putBoolean("passed",true);result.putBoolean("network_or_capture_requested",false);result.putBoolean("credentials_or_text_exported",false);finish(Activity.RESULT_OK,result);
 }catch(Throwable error){while(error.getCause()!=null)error=error.getCause();String code=error.getMessage();result.putString("error",code!=null&&code.matches("[A-Z_]{3,100}")?code:error.getClass().getSimpleName());result.putBoolean("passed",false);finish(Activity.RESULT_CANCELED,result);}finally{if(!retain&&!phase.equals("audit"))target.deleteSharedPreferences(name);}}
}
